package main

import (
	"bytes"
	"net/http"
	_ "net/http/pprof" // 暴露 /debug/pprof/heap
	"runtime"
	"sync"
)

// per-P 池化：bytes.Buffer 是典型短命对象，频繁 new 会打到 mcache 但增加 GC 标记量
var bufPool = sync.Pool{
	New: func() any { return new(bytes.Buffer) },
}

// encode 演示了 sync.Pool 正确用法的三要素：
// 1. Get 出来必须 Reset（Pool 不保证对象是干净的）
// 2. 返回前必须 copy（Put 后底层数组可能立刻被复用）
// 3. defer Put 确保归还（无论正常返回还是 panic）
func encode(s string) []byte {
	b := bufPool.Get().(*bytes.Buffer)
	b.Reset()
	defer bufPool.Put(b)
	b.WriteString(s)
	out := make([]byte, b.Len())
	copy(out, b.Bytes())
	return out
}

// 使用 GODEBUG=gctrace=1 运行时可以看到 GC 信息：
// gc 1 @0.012s 5%: 0.041+1.2+0.028 ms clock, 0.33+0.98/1.8/0+0.22 ms cpu,
//   4->5->3 MB, 4 MB goal, 0 MB stacks, 0 MB globals, 8 P
// ^GC序号 ^耗时   ^堆: before->during->after MB, ^goal, ^stack, ^globals, ^P数
//
// 此外 pprof 可以对比两种分配模式：
//   go tool pprof -alloc_objects http://localhost:6060/debug/pprof/heap
//   → 找热点函数，然后 go build -gcflags="-m" 验证逃逸
//
// sync.Pool 的关键语义：
//   - per-P 存储，减少跨 P 竞争
//   - GC 时可能把对象从 per-P 池迁移到 victim 池或丢弃
//   - 连续两次 GC 后如果对象未被 Get 回来，就会被最终回收
//   - 所以 sync.Pool 不适合做持久缓存，只适合短命、高频创建的对象

func main() {
	go http.ListenAndServe(":6060", nil)
	select {}
}
